const input = $input.first().json;
const subQuestions = input.sub_questions || [];
const query = input.query || '';
const model = input.model || 'phi3:mini';
const ollamaHost = input.ollama_host || 'http://127.0.0.1:11434';
const sessionId = input.session_id || '';

return subQuestions.map((sq, index) => ({
  json: {
    sub_question: sq,
    query: query,
    index: index,
    model: model,
    ollama_host: ollamaHost,
    session_id: sessionId
  }
}));

const item = $input.first().json;
const raw = item.data || item.body || '';

let isPdf = false;
let cleanText = raw;

// PDF & Binary Document Parser
if (typeof raw === 'string' && (raw.includes('%PDF-') || item.sub_question?.toLowerCase().includes('.pdf'))) {
  isPdf = true;
  cleanText = raw.replace(/[^a-zA-Z0-9\s.,;:()'"\/\-\[\]]/g, ' ').replace(/\s+/g, ' ');
}

return {
  json: {
    ...item,
    is_pdf: isPdf,
    extracted_content: cleanText.substring(0, 8000)
  }
};

const item = $input.first().json;
const html = item.extracted_content || item.data || '';
const blockedDomains = ['vixra.org', 'fandom.com', 'gamepedia.com', 'tradingview.com'];
const tier1Domains = ['.edu', '.gov', 'arxiv.org', 'wikipedia.org', 'docs.', 'github.com', 'ieee.org'];

let qualityScore = 0.75;
let domainTier = 'standard';

if (blockedDomains.some(d => html.toLowerCase().includes(d))) {
  qualityScore = 0.1;
  domainTier = 'blocked';
} else if (item.is_pdf || tier1Domains.some(d => html.toLowerCase().includes(d))) {
  qualityScore = 0.95;
  domainTier = 'academic_primary';
}

return {
  json: {
    ...item,
    quality_score: qualityScore,
    domain_tier: domainTier,
    is_trusted: qualityScore >= 0.5
  }
};

